window.TEAM_DATA.world.tactics=window.TEAM_DATA.world.tactics.concat(worldOriginalTactics);
for(const [teamKey,definition] of Object.entries(window.TEAM_DATA)){
  const roster=definition.roster.map(r=>r[0]);
  definition.combos=teamKey==='world'
    ?CanonCombos.worldPlayable(roster).concat(CanonCombos.worldPlanACombos.filter(move=>move.members.every(name=>roster.includes(name))))
    :CanonCombos.reviseAll(definition.combos.filter(c=>c.origin!=='原作').concat(CanonCombos.playable(roster)),roster);
}

